# Cache for live weather
weather_cache = {}
cache_time = {}

TICKER_NAMES = {
    'SPCE':'Virgin Galactic','U':'Unity Software','NVAX':'Novavax',
    'GME':'GameStop','TSLA':'Tesla','AAPL':'Apple','HOOD':'Robinhood',
    'T':'AT&T','UPST':'Upstart','RIVN':'Rivian'
}

def fetch_weather(city, lat, lon):
    url = (f'https://api.open-meteo.com/v1/forecast'
           f'?latitude={lat}&longitude={lon}'
           f'&daily=temperature_2m_max,temperature_2m_min,rain_sum,'
           f'snowfall_sum,windspeed_10m_max,weathercode'
           f'&timezone=auto&temperature_unit=fahrenheit'
           f'&precipitation_unit=inch&windspeed_unit=mph'
           f'&past_days=1&forecast_days=7')
    req = urllib.request.Request(url, headers={'User-Agent': 'TradeWeather/1.0'})
    with urllib.request.urlopen(req, timeout=15) as r:
        d = json.load(r)
    daily = d['daily']
    out = {}
    for i, dt in enumerate(daily['time']):
        out[dt] = {
            'tmax': daily['temperature_2m_max'][i] or 0,
            'tmin': daily['temperature_2m_min'][i] or 0,
            'rain': daily['rain_sum'][i] or 0,
            'snow': daily['snowfall_sum'][i] or 0,
            'wind': daily['windspeed_10m_max'][i] or 0,
            'code': daily['weathercode'][i] or 0,
        }
    return out

def refresh_weather():
    cities_done = set()
    for ticker, td in SUMMARY.items():
        city = td['city']
        if city in cities_done:
            continue
        try:
            weather_cache[city] = fetch_weather(city, td['lat'], td['lon'])
            cache_time[city] = time.time()
            cities_done.add(city)
            print(f'Weather updated: {city}')
        except Exception as e:
            print(f'Weather error {city}: {e}')

def weather_updater():
    while True:
        refresh_weather()
        time.sleep(3600)  # refresh every hour

# Start background updater
threading.Thread(target=weather_updater, daemon=True).start()

@app.route('/')
def index():
    return jsonify({'status': 'ok', 'tickers': list(SUMMARY.keys())})

@app.route('/api/weather')
def get_weather():
    return jsonify(weather_cache)

@app.route('/api/signal/<ticker>')
def get_signal(ticker):
    ticker = ticker.upper()
    if ticker not in SUMMARY:
        return jsonify({'error': 'Ticker not found'}), 404
    
    td = SUMMARY[ticker]
    city = td['city']
    weather = weather_cache.get(city, {})
    
    # US market holidays (add new ones each year)
    US_HOLIDAYS = {
        '2026-01-01','2026-01-19','2026-02-16','2026-04-03',
        '2026-05-25','2026-07-03','2026-09-07','2026-11-26','2026-12-25',
        '2025-01-01','2025-01-20','2025-02-17','2025-04-18',
        '2025-05-26','2025-07-04','2025-09-01','2025-11-27','2025-12-25',
    }
    # Get next trading day (skip weekends and holidays)
    dt = datetime.now() + timedelta(days=1)
    while dt.weekday() >= 5 or dt.strftime('%Y-%m-%d') in US_HOLIDAYS:
        dt += timedelta(days=1)
    tomorrow = dt.strftime('%Y-%m-%d')
    
    wd = weather.get(tomorrow)
    
    result = {
        'ticker': ticker,
        'name': TICKER_NAMES.get(ticker, ticker),
        'city': city,
        'n_bull': td['n_bull'],
        'n_bear': td['n_bear'],
        'score': td['score'],
        'tomorrow': tomorrow,
        'weather': wd,
        'patterns_count': len(td['patterns']),
    }
    
    if wd:
        result['signal'] = compute_signal(tomorrow, wd, td['patterns'])
    
    return jsonify(result)

@app.route('/api/forecast/<ticker>')
def get_forecast(ticker):
    ticker = ticker.upper()
    if ticker not in SUMMARY:
        return jsonify({'error': 'Ticker not found'}), 404
    
    td = SUMMARY[ticker]
    city = td['city']
    weather = weather_cache.get(city, {})
    
    forecast = []
    dt = datetime.now() + timedelta(days=1)
    days_added = 0
    while days_added < 5:
        if dt.weekday() < 5:
            ds = dt.strftime('%Y-%m-%d')
            wd = weather.get(ds)
            day_data = {'date': ds, 'dow': ['Mon','Tue','Wed','Thu','Fri'][dt.weekday()]}
            if wd:
                day_data['weather'] = wd
                day_data['signal'] = compute_signal(ds, wd, td['patterns'])
            forecast.append(day_data)
            days_added += 1
        dt += timedelta(days=1)
    
    return jsonify({'ticker': ticker, 'city': city, 'forecast': forecast})

def compute_signal(ds, wd, patterns):
    MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
    DAYS = ['Mon','Tue','Wed','Thu','Fri']
    
    dt = datetime.strptime(ds, '%Y-%m-%d')
    m = dt.month
    dow = DAYS[dt.weekday()] if dt.weekday() < 5 else None
    if not dow: return None
    wk = (dt.day - 1) // 7 + 1
    mon = MONTHS[m-1]
    season = ('Winter' if m in [12,1,2] else 'Spring' if m in [3,4,5]
              else 'Summer' if m in [6,7,8] else 'Fall')
    
    tmax = wd['tmax']; tmin = wd['tmin']; rain = wd['rain']; snow = wd['snow']; code = wd['code']
    tmean = (tmax+tmin)/2
    
    if snow > 0.05: wtype = 'snowy'
    elif code >= 95 and rain > 0.1: wtype = 'rainy'
    elif code >= 95: wtype = 'cloudy'
    elif code >= 80: wtype = 'rainy'
    elif code >= 61: wtype = 'rainy'
    elif code >= 51: wtype = 'drizzle'
    elif code >= 45: wtype = 'cloudy'
    elif rain > 0.1: wtype = 'rainy'
    elif rain > 0.01: wtype = 'drizzle'
    elif code == 0: wtype = 'clear'
    elif code == 1: wtype = 'clear'
    elif code == 2: wtype = 'cloudy'
    elif code <= 3: wtype = 'cloudy'
    else: wtype = 'cloudy'
    
    is_rainy = wtype in ['rainy','drizzle']
    is_clear = wtype == 'clear'
    is_cloudy = wtype == 'cloudy'
    is_snowy = wtype == 'snowy'
    is_hot = tmean > 80; is_warm = 65<=tmean<=80; is_cool = 50<=tmean<65; is_cold = tmean<50
    
    matched = []
    for p in patterns:
        pat = p['pattern']
        m_flag = False
        if pat==f'{mon} {dow}': m_flag=True
        elif pat==f'Any {dow}': m_flag=True
        elif pat==f'{dow} week{wk}': m_flag=True
        elif pat==f'{season} {dow}': m_flag=True
        elif pat==f'{dow} + rainy' and is_rainy: m_flag=True
        elif pat==f'{dow} + clear' and is_clear: m_flag=True
        elif pat==f'{dow} + cloudy' and is_cloudy: m_flag=True
        elif pat==f'{dow} + snowy' and is_snowy: m_flag=True
        elif pat==f'{dow} + hot' and is_hot: m_flag=True
        elif pat==f'{dow} + warm' and is_warm: m_flag=True
        elif pat==f'{dow} + cool' and is_cool: m_flag=True
        elif pat==f'{dow} + cold' and is_cold: m_flag=True
        elif pat==f'{dow} week{wk} + rainy' and is_rainy: m_flag=True
        elif pat==f'{dow} week{wk} + clear' and is_clear: m_flag=True
        elif pat==f'{dow} week{wk} + cloudy' and is_cloudy: m_flag=True
        elif pat==f'{season} {dow} + rainy' and is_rainy: m_flag=True
        elif pat==f'{season} {dow} + clear' and is_clear: m_flag=True
        elif pat==f'{season} {dow} + cloudy' and is_cloudy: m_flag=True
        elif pat==f'{season} {dow} + hot' and is_hot: m_flag=True
        elif pat==f'{season} {dow} + warm' and is_warm: m_flag=True
        elif pat==f'{season} {dow} + cool' and is_cool: m_flag=True
        elif pat==f'{season} {dow} + cold' and is_cold: m_flag=True
        elif pat==f'{mon} {dow} + rainy' and is_rainy: m_flag=True
        elif pat==f'{mon} {dow} + clear' and is_clear: m_flag=True
        elif pat==f'{mon} {dow} + cloudy' and is_cloudy: m_flag=True
        if m_flag: matched.append(p)
    
    if not matched:
        return {'signal': 'neutral', 'win_rate': 50, 'avg_ret': 0, 'matched': 0, 'top_patterns': []}
    
    tw = wwr = wret = 0
    for p in matched:
        w = math.log(p['n']+1)
        wwr += p['win_rate']*w; wret += p['avg_ret']*w; tw += w
    wr = wwr/tw; ret = wret/tw
    sig = 'bull' if wr>=58 else 'bear' if wr<=42 else 'neutral'
    
    top = sorted(matched, key=lambda x: abs(x['win_rate']-50), reverse=True)[:5]
    return {'signal': sig, 'win_rate': round(wr,1), 'avg_ret': round(ret,3),
            'matched': len(matched), 'top_patterns': top}

if __name__ == '__main__':
    refresh_weather()
    app.run(host='0.0.0.0', port=8080)
